import{_ as e,o,c as s,a2 as t}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"安全中心 - 修改密码","description":"","frontmatter":{"title":"安全中心 - 修改密码"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/change-password.md","filePath":"ops-knowledge-base/presales-support/change-password.md","lastUpdated":1788259091000}'),r={name:"ops-knowledge-base/presales-support/change-password.md"};function l(n,a,i,p,d,g){return o(),s("div",null,[...a[0]||(a[0]=[t('<p>平台修改密码，用于用户更改账户密码。以下是该功能的相关介绍：</p><h3 id="一、功能入口" tabindex="-1">一、功能入口 <a class="header-anchor" href="#一、功能入口" aria-label="Permalink to &quot;一、功能入口&quot;">​</a></h3><p>用户可通过 “后台右上角头像 /安全中心 / 修改密码” 路径，进入密码修改界面，进行密码更新操作。</p><h3 id="二、操作指南" tabindex="-1">二、操作指南 <a class="header-anchor" href="#二、操作指南" aria-label="Permalink to &quot;二、操作指南&quot;">​</a></h3><ol><li><p><strong>输入当前密码</strong>：在 “当前密码” 输入框中，准确填写用户当前正在使用的账户密码，以验证身份。</p></li><li><p><strong>设置新密码</strong>：</p><ul><li>在 “新密码” 输入框中填写新的密码。用户也可点击 “生成密码” 按钮，系统将自动生成一个高强度密码供用户使用。</li><li>为确保密码安全性，平台建议设置高强度密码，具体要求包括：同时使用大小写字符、至少使用一个符号（如 #、$、!、%、&amp; 等）、不要使用连续字符。</li></ul></li><li><p><strong>确认新密码</strong>：在 “确认新密码” 输入框中再次填写新设置的密码，以确保两次输入的密码一致，避免因输入错误导致密码设置失败。</p></li><li><p><strong>保存修改</strong>：信息填写完毕且确认无误后，点击 “保存修改” 按钮，完成密码修改；若放弃操作，可点击 “取消”。</p></li></ol><h3 id="三、注意事项" tabindex="-1">三、注意事项 <a class="header-anchor" href="#三、注意事项" aria-label="Permalink to &quot;三、注意事项&quot;">​</a></h3><ol><li><strong>密码安全性</strong>：请务必设置符合平台要求的高强度密码，避免使用过于简单或容易被猜测的密码，如生日、连续数字等，以保障账户安全。</li><li><strong>密码一致性</strong>：在输入新密码和确认新密码时，请注意仔细核对，确保两次输入完全一致，以免因密码不一致导致修改失败。</li><li><strong>密码保管</strong>：新密码设置完成后，请妥善保管，勿向他人泄露。平台将采取安全技术措施保障用户密码安全，但用户自身也需提高安全意识，防止密码被盗用。</li><li><strong>定期修改</strong>：为进一步提升账户安全性，建议用户定期修改密码，如每 3 个月或 6 个月更换一次，降低密码被破解的风险。</li></ol>',7)])])}const _=e(r,[["render",l]]);export{h as __pageData,_ as default};
